import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto("https://staging.nxeon.cloud/login", { waitUntil: "networkidle" });

async function checkLabelFocus(labelText, expectedId) {
  // Click on the label text itself (not the input)
  const label = page.locator(`label:text-is("${labelText}")`);
  await label.click();
  const focusedId = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const forAttr = await label.getAttribute("for");
  console.log(`Label "${labelText}": for="${forAttr}" -> focused element id="${focusedId}" (expected "${expectedId}")`);
  return focusedId === expectedId && forAttr === expectedId;
}

const emailOk = await checkLabelFocus("Email", "login-email");
const passOk = await checkLabelFocus("Password", "login-password");

await browser.close();

console.log("Email label focus test:", emailOk ? "PASS" : "FAIL");
console.log("Password label focus test:", passOk ? "PASS" : "FAIL");

if (!emailOk || !passOk) process.exit(1);

